/* TU rva 0x983b0..0x98430, 2 rows — generated by tools/regroup.py plan */
/* v4: the three -1 stores use the COMMON old-ofs base with element
 * indices [0],[1],[2] (FA's disps -0x30/-0x2c/-0x28 relative to f14 + the
 * advanced esi), and ofs += 48 moved after the stores (FA schedules the
 * esi advance early with compensating negative disps). */
extern void *memset(void *, int, unsigned);

struct W36G_WRAP { long d[12]; };
struct W36G_SQ { unsigned long f0, f4, f8, fc, f10; struct W36G_WRAP *f14; };

void InitializeQueue(struct W36G_SQ *q, struct W36G_WRAP *w, long n)
{
    long ofs;
    q->f14 = w;
    q->f0 = 0;
    q->f4 = 0;
    q->fc = 0;
    q->f10 = 0;
    q->f8 = n;
    if (n > 0) {
        ofs = 0;
        do {
            memset((char *)q->f14 + ofs, 0, 48);
            ((long *)((char *)q->f14 + ofs))[0] = -1;
            ((long *)((char *)q->f14 + ofs))[1] = -1;
            ((long *)((char *)q->f14 + ofs))[2] = -1;
            ofs += 48;
            n--;
        } while (n != 0);
    }
}

// ?updateQueueHead@@YAXAAUSERIAL_QUEUE@@J@Z @ rva 0x98410 (32 B) — FA asm
//   (no relocs at all): 8b 44 24 08 (arg2 j = eax)/85 c0 (test)/7c 0a
//   (jl ret)/8b 4c 24 04 (arg1 q = ecx)/99 (cdq)/f7 79 08 (idiv [ecx+8])/
//   89 11 (mov [ecx],edx — remainder)/c3 (Y-mangle = cdecl, bare ret).
//   if (j >= 0) q->head = j mod q->capacity.  Plain C: CL keeps j in eax
//   across the test, loads the ref pointer into ecx for the divide, and
//   stores the edx remainder — same plan.  First draft fell to __stdcall
//   (c2 08 ret); b20f_updateQueueHead (cdecl) exact.  Probe
//   build/w4probe/b20f_updateQueueHead.obj — exact (no fixups).
void __cdecl updateQueueHead_q(void *q, long j)
{
    if (j >= 0)
        *(long *)q = j % ((long *)q)[2];
}

